// Before: Manual hooks required
function ProductTable({ items, onSelect }) {
  const sortedItems = useMemo(() => {
    return [...items].sort((a, b) => a.name.localeCompare(b.name));
  }, [items]);

  const handleRowClick = useCallback((id) => {
    onSelect(id);
  }, [onSelect]);

  return <Table data={sortedItems} onClick={handleRowClick} />;
}

// After: Clean, declarative React 19 code with zero memo hooks
function ProductTable({ items, onSelect }) {
  const sortedItems = [...items].sort((a, b) => a.name.localeCompare(b.name));
  const handleRowClick = (id) => onSelect(id);

  return <Table data={sortedItems} onClick={handleRowClick} />;
}
